 plate(g,16,24,.8,top,mat('#14161a',.1,.5),.5,[],0,-11.6);box(g,12,2.3,15,0,top+.8+1.15,-7.5,silver());text(g,'ESP8266MOD',0,top+3.15,-9,10,1.4,'#55595d');text(g,'AI-THINKER',0,top+3.15,-5.8,8,1,'#55595d');
